from lib import *
r=[]
r.append(R(6553785,"ओटमील कांजी",
"पारंपरिक रूप से उच्च कार्ब वाले दलिए का यह रूप साबुत अनाज और सेहतमंद बनाना आसान है।",
"4","¾ कप दलिया + 1 अंडा + 1 ½ छोटा चम्मच हरा प्याज़ और धनिया पत्ती",
["1 कप ओल्ड-फ़ैशन्ड रोल्ड ओट्स","4 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","1 कप सफ़ेद (बटन) मशरूम (स्लाइस किए हुए)","1 बड़ा चम्मच नीबू का रस","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","4 बड़े अंडे","2 डंठल हरा प्याज़ (स्कैलियन) (स्लाइस किए हुए)","1 बड़ा चम्मच धनिया पत्ती (बारीक कटी हुई)"],
["ओट्स, ब्रॉथ और सोया सॉस को एक सॉसपैन में तेज़ आँच पर डालें। उबाल आने दें, फिर आँच कम करके ओट्स के नरम होने तक धीमी आँच पर पकाएँ, लगभग 10 मिनट।","एक छोटे नॉनस्टिक सॉते पैन पर कुकिंग स्प्रे लगाएँ। मशरूम डालें और नरम होने तक और सारा तरल सूखने तक भूनें, लगभग 4 मिनट। नीबू का रस डालें और तरल सूखने तक भूनें। मशरूम को ओटमील के दलिए में मिलाएँ।","सॉते पैन को साफ़ करें, फिर कुकिंग स्प्रे लगाएँ। अंडों को तब तक तलें जब तक ज़र्दी बस जम न जाए।","एक कटोरे में ¾ कप ओटमील का दलिया डालें, ऊपर एक तला हुआ अंडा और 1 ½ छोटा चम्मच हरा प्याज़ और धनिया पत्ती डालें। बाक़ी 3 कटोरों के लिए यही प्रक्रिया दोहराएँ।"]))
r.append(R(6554653,"शकरकंद होम फ़्राइज़",
"चाहे आप इन्हें नाश्ते, दोपहर या रात के खाने में परोसें, शकरकंद के होम फ़्राइज़ हमेशा परिवार के पसंदीदा होते हैं। लुभावने मसालों के साथ यह रेसिपी ऐसी होगी जिसे आप बार-बार बनाने के लिए सहेजकर रखना चाहेंगे।",
"6","1/2 कप",
["2 बड़े चम्मच जैतून का तेल","2 बड़े शकरकंद (छिले हुए और छोटे चौकोर टुकड़ों में कटे हुए)","1 छोटा चम्मच स्मोक्ड पैपरिका","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच प्याज़ पाउडर","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["एक बड़ी कड़ाही में मध्यम आँच पर जैतून का तेल गरम करें।","कटे हुए शकरकंद को कड़ाही में डालें और एक परत में फैलाएँ।","शकरकंद को 15–20 मिनट तक, बीच-बीच में चलाते हुए, तब तक भूनें जब तक वे अंदर से नरम और बाहर से कुरकुरे न हो जाएँ।","शकरकंद पर स्मोक्ड पैपरिका, लहसुन पाउडर, प्याज़ पाउडर, नमक और काली मिर्च छिड़कें। बराबर लगाने के लिए उछालकर मिलाएँ।","5 मिनट और पकाएँ ताकि मसाले शकरकंद में अच्छी तरह मिल जाएँ।","कड़ाही को आँच से उतार लें।","चाहें तो कटे हुए ताज़े अजमोद से सजाएँ।"]))
r.append(R(6555967,"फूलगोभी के चावल पर करी टमाटर नारियल दाल",
"यह बिल्कुल सही मसालेदार करी टमाटर नारियल दाल एक शाकाहारी व्यंजन है जो पौष्टिक और मधुमेह के अनुकूल विकल्प भी है।",
"4","3/4 कप + 1 कप फूलगोभी के चावल",
["1 छोटा चम्मच जैतून का तेल","1 मध्यम पीला प्याज़ (बारीक कटा हुआ)","3 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच ताज़ा अदरक (कसा हुआ)","2 बड़े चम्मच करी पाउडर","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच पिसा धनिया","1/2 छोटा चम्मच हल्दी","1/4 छोटा चम्मच लाल मिर्च (केयेन)","1/4 छोटा चम्मच नमक","1 कप मसूर की दाल (हरी या भूरी, सूखी, धुली हुई)","1 (14 औंस) डिब्बा डिब्बाबंद कटे हुए टमाटर (कम सोडियम वाले)","½ (14 औंस) डिब्बा लाइट नारियल का दूध","4 कप जमे हुए फूलगोभी के चावल (भाप में पकाए हुए)","2 बड़े चम्मच ताज़ा अजमोद (या धनिया पत्ती, कटी हुई)"],
["एक बड़े बर्तन में मध्यम आँच पर जैतून का तेल गरम करें। कटा हुआ प्याज़ डालें और पारदर्शी होने तक भूनें, लगभग 5 मिनट।","बर्तन में कटा हुआ लहसुन और कसा हुआ अदरक डालें। खुशबू आने तक 2 मिनट और भूनें।","करी पाउडर, पिसा जीरा, पिसा धनिया, हल्दी और लाल मिर्च (केयेन) डालकर मिलाएँ। मसालों को प्याज़ के मिश्रण के साथ 1–2 मिनट पकाएँ।","बर्तन में धुली हुई दाल, कटे हुए टमाटर और नारियल का दूध डालें। अच्छी तरह मिलाएँ।","मिश्रण में उबाल आने दें, फिर आँच धीमी कर दें। बर्तन को ढक दें और 20–25 मिनट धीमी आँच पर पकाएँ, या जब तक दाल नरम न हो जाए।","भाप में पकाए फूलगोभी के चावल के ऊपर परोसें और चाहें तो कटे हुए ताज़े अजमोद या धनिया पत्ती से सजाएँ।"]))
r.append(R(6556196,"शाकाहारी ब्रेकफ़ास्ट बरिटो बाउल",
"यह रंगीन और सब्ज़ियों से भरा ब्रेकफ़ास्ट बरिटो बाउल सफ़ेद चावल की जगह साबुत अनाज वाले क्विनोआ को आधार बनाकर क्लासिक व्यंजन को नया रूप देता है। इस रेसिपी को नाश्ते, दोपहर या रात के खाने में इस्तेमाल किया जा सकता है क्योंकि यह फ़ाइबर का उत्कृष्ट स्रोत, प्रोटीन का अच्छा स्रोत है और इसमें बिना स्टार्च वाली सब्ज़ियाँ शामिल हैं।",
"4","1 बाउल",
["1 कप क्विनोआ (बिना नमक या वसा के पकाया हुआ)","1 कप अंडे का विकल्प","1 कप काली बीन्स (धुली और पानी निथारी हुई)","1 कप चेरी टमाटर (आधे कटे हुए)","1 मध्यम एवोकाडो (टुकड़ों में कटा हुआ, वैकल्पिक: कम वसा के लिए आधा इस्तेमाल करें)","1 कप बेबी पालक (कटा हुआ)","1 छोटा चम्मच जैतून का तेल","1/2 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच स्मोक्ड पैपरिका","1 साबुत नीबू का रस"],
["एक नॉन-स्टिक कड़ाही में मध्यम आँच पर जैतून का तेल गरम करें। पालक डालें और गलने तक भूनें (लगभग 2 मिनट)।","अंडे के विकल्प को जीरा और पैपरिका के साथ फेंटें, फिर पालक वाली कड़ाही में डालें। पूरी तरह पकने तक भुर्जी की तरह चलाते हुए पकाएँ।","बाउल तैयार करें। पका हुआ क्विनोआ, काली बीन्स, टमाटर, एवोकाडो और भुर्जी को 4 बाउल में बराबर बाँटें।","ऊपर से नीबू का रस डालें।"]))
r.append(R(6556304,"रैप के लिए लेट्यूस",
"लेट्यूस रैप की पोषण संबंधी जानकारी",
"1","2 लेट्यूस पत्ते",["2 पत्ते लेट्यूस के पत्ते (धुले हुए)"],[]))
r.append(R(6556849,"कद्दू-केला मफ़िन",
"इन कद्दू-केला मफ़िन के साथ अपनी सुबह की शुरुआत एक मीठे, मधुमेह के अनुकूल व्यंजन से करें। दुकान से ख़रीदे मफ़िन से कम कार्ब वाले, इन्हें एक कप कॉफ़ी के साथ लें और अपने दिन की एकदम सही शुरुआत करें।\n\nअपने नाश्ते को कुछ सब्ज़ियों और प्रोटीन के साथ पूरा करने के लिए माइक्रोवेव एग एंड वेजी जार या स्पिनच एंड एग बाइट्स भी जोड़ें!",
"12","1 मफ़िन",
["1 1/2 कप सफ़ेद साबुत गेहूँ का आटा","1/3 कप ब्राउन शुगर","1 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच नमक","2 छोटे चम्मच पंपकिन पाई मसाला","2 अंडे","1 कप कद्दू की प्यूरी","3 बड़े चम्मच कैनोला तेल","1 छोटा केला (मसला हुआ)","1 छोटा चम्मच वेनिला एक्सट्रैक्ट","1/4 कप अखरोट (बारीक कटे हुए)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें और मफ़िन टिन में लाइनर लगाएँ।","एक बड़े कटोरे में आटा, चीनी, बेकिंग सोडा, नमक और पंपकिन पाई मसाला मिलाएँ।","एक छोटे कटोरे में अंडे, कद्दू की प्यूरी, तेल, केला और वेनिला मिलाएँ।","गीली सामग्री को सूखी सामग्री में डालें और मिलने तक चलाएँ। अखरोट को धीरे से मिलाएँ।","घोल को मफ़िन टिन में डालें और 18-20 मिनट तक बेक करें, जब तक टूथपिक साफ़ न निकले।"]))
r.append(R(6557494,"साउथवेस्ट-स्टाइल टर्की मीटलोफ़",
"मीटलोफ़, हैमबर्गर और मीटबॉल जैसे प्रोटीन वाले व्यंजनों में साबुत अनाज शामिल करने का एक अच्छा तरीका है कि सामान्य ब्रेड क्रम्ब्स की जगह जल्दी पकने वाले ओट्स का उपयोग करें। ओट्स में मौजूद फ़ाइबर कोलेस्ट्रॉल कम करने में मदद करता पाया गया है। अपनी थाली पूरी करें: क्लासिक \"मांस-और-आलू\" भोजन के लिए इसे मसले हुए लाल आलू के साथ परोसें। संतुलित भोजन के लिए संतरा और एवोकाडो वाला हरा सलाद जोड़ें।",
"8","1 स्लाइस",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 1/2 पाउंड कम चर्बी वाली कीमा टर्की","1 कप जल्दी पकने वाले ओट्स","1 बड़ा पीला प्याज़ (बारीक कटा हुआ)","2 बड़े अंडे (फेंटे हुए)","1 मध्यम हरी शिमला मिर्च (बारीक टुकड़ों में कटी हुई)","1/2 कप केचप","3 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच चिली पाउडर","2 छोटे चम्मच पिसा जीरा","1 छोटा चम्मच सूखा ओरेगानो","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 350°F पर पहले से गरम करें। 9 × 5 इंच के लोफ़ पैन पर नॉनस्टिक कुकिंग स्प्रे लगाएँ।","बाक़ी सारी सामग्री एक बड़े कटोरे में डालें। सामग्री को अच्छी तरह मिलने तक धीरे से मिलाएँ।","मिश्रण को तैयार लोफ़ पैन में चम्मच से डालें और चम्मच के पिछले हिस्से या स्पैचुला से ऊपरी सतह को बराबर करें। लोफ़ पैन को ओवन में रखें और तब तक बेक करें जब तक मीटलोफ़ के बीच में डाला गया थर्मामीटर 165°F दिखाए, 1 घंटा।"]))
r.append(R(6558356,"मेपल सेब",
"सेब को भूनने से उनकी प्राकृतिक शर्करा कैरामेलाइज़ होती है और भरपूर, मीठा स्वाद बनता है। इन सेबों को सेब के साइडर और शुगर-फ़्री मेपल सिरप से बने कम चीनी वाले सिरप में मिलाया जाता है, जिससे एक स्वादिष्ट, मधुमेह के अनुकूल मिठाई बनती है। या इसे सादे ग्रीक योगर्ट के ऊपर परोसें, एक मीठे लेकिन पेट भरने वाले नाश्ते के लिए।",
"4","1/2 सेब",
["2 मध्यम ग्रैनी स्मिथ या कोई अन्य खट्टा सेब (बिना छिले और 1/2 इंच की फाँकों में कटे हुए)","1 बड़ा चम्मच नीबू का रस","1 छोटा चम्मच कैनोला तेल","1/4 कप सेब का साइडर","1 बड़ा चम्मच शुगर-फ़्री मेपल-टाइप सिरप","1/4 छोटा चम्मच पिसी लौंग","1/4 छोटा चम्मच पिसी दालचीनी","1 बड़ा चम्मच पतले कटे बादाम (भुने हुए)"],
["सेब के स्लाइस को नीबू के रस के साथ मिलाएँ।","एक बड़ी कड़ाही में मध्यम आँच पर तेल गरम करें। सेब डालें और 3 मिनट भूनें। आँच धीमी करें, ढक दें और बीच-बीच में चलाते हुए लगभग 6 से 7 मिनट धीमी आँच पर पकाएँ। सेब को पैन से निकालकर अलग रख दें।","उसी कड़ाही में बादाम को छोड़कर बाक़ी सारी सामग्री डालें। उबाल आने दें और मध्यम-तेज़ आँच पर सिरप जैसा होने तक पकाएँ, पैन में बचे सेब के टुकड़ों को खुरचते रहें। सेब को वापस डालें और ऊपर से कटे हुए बादाम छिड़कें।"]))
r.append(R(6558830,"स्पैगेटी स्क्वैश \"रामेन\" नूडल बाउल",
"ट्रेंडी रामेन नूडल बाउल का यह ज़्यादा सेहतमंद रूप एक स्वादिष्ट शोरबा देता है जिसे आप अपनी पसंद से बदल सकते हैं। चिकन या शिमला मिर्च नहीं हैं? इसे अन्य प्रोटीन और सब्ज़ियों, जैसे झींगे, बीन स्प्राउट्स और कसी हुई गाजर के साथ बदलकर देखें।",
"4","1 बाउल",
["2 छोटे चम्मच भुना हुआ तिल का तेल","2 1/2 छोटे चम्मच कम सोडियम वाला सोया सॉस","4 कप कम सोडियम वाला चिकन ब्रॉथ (फ़ैट-फ़्री)","2 1/2 पाउंड स्पैगेटी स्क्वैश (मध्यम)","2 कप पका हुआ चिकन (रेशों में कटा हुआ)","1 छोटा चम्मच एशियाई शैली का हॉट सॉस ((जैसे साम्बल ओएलेक))","1/2 छोटा चम्मच फ़िश सॉस","1/2 कप हरा प्याज़ (स्कैलियन) (पतले स्लाइस में कटा हुआ, सफ़ेद और हरे दोनों हिस्से)","1/2 कप लाल शिमला मिर्च (पतली कटी हुई (1 इंच लंबी))","1 साबुत नीबू (चार टुकड़ों में कटा हुआ, परोसने के लिए)"],
["ओवन को 400° F पर पहले से गरम करें। 9x13 इंच के काँच या धातु के बेकिंग डिश में 2 इंच पानी भरें। स्पैगेटी स्क्वैश के सिरे काटें, फिर उसे लंबाई में आधा काटें। स्क्वैश को कटी हुई सतह नीचे की ओर रखकर पैन में रखें और 40 मिनट बेक करें। ओवन से निकालें और स्क्वैश को तुरंत पैन से निकाल लें। बीज निकालकर फेंक दें। काँटे से स्क्वैश को छिलके से खुरचकर निकालें और अलग रख दें। इससे 4 कप पका हुआ स्क्वैश बनता है।","जब स्क्वैश पक रहा हो, एक मध्यम सॉसपैन में मध्यम आँच पर ब्रॉथ को उबाल आने तक गरम करें। सोया सॉस, तिल का तेल, फ़िश सॉस और हॉट सॉस डालें। 2 मिनट धीमी आँच पर पकाएँ। चिकन डालें और 2 मिनट तक गरम करें।","एक सूप बाउल में 1 कप स्क्वैश रखें। स्क्वैश पर 1 कप ब्रॉथ डालें और 1/2 कप चिकन डालें। ऊपर 2 बड़े चम्मच हरा प्याज़ और 2 बड़े चम्मच शिमला मिर्च की पट्टियाँ रखें।","बाक़ी तीन बाउल के लिए यही प्रक्रिया दोहराएँ। परोसने के लिए हर बाउल में 1 नीबू की फाँक डालें।"]))
r.append(R(6560352,"गाजर के साथ मलाईदार मसले हुए पार्सनिप",
"मिट्टी जैसे स्वाद वाले पार्सनिप और मीठी गाजर का एक लज़ीज़ मिश्रण इस स्वादिष्ट, मधुमेह के अनुकूल साइड डिश में एक साथ आता है।",
"4","1/2 कप",
["4 मध्यम पार्सनिप (छिले हुए और कटे हुए)","2 मध्यम गाजर (छिली हुई और कटी हुई)","2 बड़े चम्मच बिना नमक का मक्खन","1/4 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच ताज़ा अजमोद (कटा हुआ, सजाने के लिए)"],
["एक बड़े बर्तन में पानी उबालें। कटे हुए पार्सनिप और गाजर को उबलते पानी में डालें।","15–20 मिनट तक पकाएँ, या जब तक पार्सनिप और गाजर काँटे से आसानी से न धँसने लगें।","पार्सनिप और गाजर का पानी निथारें और उन्हें वापस बर्तन में डालें।","बर्तन में बिना नमक का मक्खन डालें और आलू मैशर या काँटे से पार्सनिप और गाजर को मसलें।","मसलना जारी रखते हुए धीरे-धीरे वेजिटेबल ब्रॉथ डालें, जब तक मनचाही मलाईदार गाढ़ापन न आ जाए।","नमक और काली मिर्च डालें। अच्छी तरह मिलाएँ।"]))
r.append(R(6560917,"बेहतर मसले हुए आलू",
"ये बेहतर मसले हुए आलू सरल सामग्री और हल्के अंदाज़ में बनी एक मलाईदार, आरामदायक साइड डिश हैं। ये आपकी पसंद की चिकनी बनावट और भरपूर स्वाद बनाए रखते हैं, साथ ही छोटे बदलावों से आपके भोजन में बिना स्टार्च वाली और सब्ज़ियाँ जोड़ते हैं। बनाने में आसान, ये रोज़ के भोजन या ख़ास मौक़ों के लिए एक बढ़िया जोड़ हैं।",
"10","1/2 कप",
["1/2 छोटा चम्मच काली मिर्च","1 छोटा चम्मच नमक","2 छोटे चम्मच मक्खन (बिना नमक का मक्खन)","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच पारमेज़न चीज़ (कसा हुआ)","1/3 कप कम वसा वाली छाछ (बटरमिल्क)","1 फूलगोभी (छोटे फूलों में अलग की हुई, बीच का हिस्सा और डंठल फेंक दें)","5 कली लहसुन (छिली हुई और साबुत छोड़ी हुई)","7 औंस रसेट या बेकिंग आलू (छिले हुए और 2 इंच के टुकड़ों में कटे हुए)"],
["एक बड़े बर्तन में आलू, लहसुन और फूलगोभी रखें। सब कुछ पूरी तरह डूबने जितना पानी डालें। उबाल आने दें, आँच मध्यम करें और आलू और फूलगोभी के नरम होने तक पकाएँ, लगभग 15 मिनट।","पानी निथारें और सब्ज़ियों और लहसुन को वापस बर्तन में डालें। बर्तन को रसोई के तौलिये से ढकें और तौलिये के ऊपर ढक्कन रखें। 5 मिनट रहने दें। ढक्कन और तौलिया हटा दें। यह प्रक्रिया सब्ज़ियों को सुखाने में मदद करती है ताकि वे बेहतर मसली जा सकें।","छाछ, चीज़, जैतून का तेल, मक्खन, नमक और काली मिर्च डालें। सामग्री के बस हल्के से मिलने तक ही मसलें। चाहें तो ताज़ी कतरी हुई चाइव्स से सजाएँ।"]))
r.append(R(6561298,"स्कैलप्ड पोटैटोज़",
"आलू के व्यंजन त्योहारों में आम होते हैं। इस मलाईदार आलू की साइड डिश को अपने त्योहारी रात के खाने में परोसें। किसी को पता भी नहीं चलेगा कि यह स्कैलप्ड पोटैटोज़ का \"सेहतमंद\" संस्करण है!",
"8","1/2 कप",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/4 छोटा चम्मच नमक (वैकल्पिक)","6 मध्यम रसेट या बेकिंग आलू","1 मध्यम पीला प्याज़ (पतली पट्टियों में कटा हुआ)","1/4 छोटा चम्मच काली मिर्च","1 कप फ़ैट-फ़्री हाफ़-एंड-हाफ़","1/2 कप चेडर चीज़ (कम चर्बी वाला, कसा हुआ तीखा, बाँटकर उपयोग)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। आलू छीलें और पतले गोल टुकड़ों में काटें।","एक बड़ी नॉनस्टिक कड़ाही पर कुकिंग स्प्रे लगाएँ और प्याज़ को मध्यम-तेज़ आँच पर पारदर्शी होने तक भूनें।","पाई पैन या 8 इंच के गोल केक पैन पर कुकिंग स्प्रे करें।","पैन की तली में आलू और प्याज़ की मोटी परत (लगभग आधा) रखें।","हाफ़-एंड-हाफ़ में नमक और काली मिर्च मिलाएँ। आलू पर 1/2 कप हाफ़-एंड-हाफ़ डालें। ऊपर से 1/4 कप चीज़ छिड़कें।","बचे हुए आलू डालें और उन पर 1/2 कप हाफ़-एंड-हाफ़ डालें और बचे हुए चीज़ से ढकें।","40 मिनट बेक करें या जब तक आलू नरम न हो जाएँ।"]))
r.append(R(6561472,"काली बीन्स और मक्के का सलाद",
"यह सलाद वसंत के पिकनिक या झटपट दोपहर के भोजन के लिए एकदम सही है और फ़ाइबर से भरा हुआ है।",
"12","1/2 कप",
["2 (14.5 औंस के) डिब्बे काली बीन्स (धुली और पानी निथारी हुई)","2 कप जमा हुआ मक्का (पिघलाया हुआ)","1 लाल शिमला मिर्च (बारीक टुकड़ों में कटी हुई)","1/2 कप बारीक कटा हुआ लाल प्याज़","1/2 कप कटी हुई ताज़ा धनिया पत्ती","2 छोटे नीबू (रस निकाला हुआ)","3 बड़े चम्मच जैतून का तेल","1/2 छोटा चम्मच जीरा","1/4 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच लाल मिर्च (केयेन) (वैकल्पिक)"],
["एक मध्यम कटोरे में बीन्स, मक्का, लाल शिमला मिर्च, लाल प्याज़ और धनिया पत्ती मिलाएँ।","एक छोटे कटोरे में बाक़ी सामग्री को फेंटकर मिलाएँ और बीन्स के सलाद पर डालें। लपेटने के लिए उछालें।"]))
r.append(R(6561654,"भूमध्यसागरीय खीरे का सलाद",
"यह मलाईदार भूमध्यसागरीय खीरे का सलाद एक कुरकुरी, कम कार्ब वाली साइड डिश है जो गर्मियों की शाम के लिए एकदम सही है।",
"6","½ कप",
["2 मध्यम खीरे (गोल स्लाइस में कटे हुए)","1/4 मध्यम लाल प्याज़ (स्लाइस किया हुआ)","2 बड़े चम्मच ताज़ा सोआ","2 बड़े चम्मच पिस्ता (बारीक कटे हुए)","2 बड़े चम्मच सादा फ़ैट-फ़्री ग्रीक योगर्ट","1 बड़ा चम्मच जैतून का तेल","1 बड़ा चम्मच रेड वाइन सिरका","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["एक कटोरे में खीरे, लाल प्याज़, सोआ और पिस्ता मिलाएँ।","एक अलग छोटे कटोरे में ग्रीक योगर्ट, जैतून का तेल, रेड वाइन सिरका, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को खीरे के मिश्रण पर डालें और लपेटने के लिए उछालें।"]))
r.append(R(6562027,"सोया-ग्लेज़्ड मशरूम और सब्ज़ियों वाले ब्राउन राइस के साथ पैन-सियर्ड सैल्मन",
"यह संतुलित सैल्मन व्यंजन कुरकुरे पैन-सियर्ड फ़िले को स्वादिष्ट सोया-ग्लेज़्ड मशरूम और सब्ज़ियों से भरे ब्राउन राइस पुलाव के साथ जोड़ता है। हृदय के लिए स्वस्थ वसा, फ़ाइबर से भरपूर साबुत अनाज और एंटीऑक्सीडेंट से भरी सब्ज़ियों का मेल इसे संतोषजनक और पौष्टिक दोनों बनाता है। समझदारी से डाले गए मसालों और बिना अतिरिक्त चीनी के, यह मधुमेह वाले लोगों के लिए रक्त ग्लूकोज़ (ब्लड शुगर) के अनुकूल विकल्प है जो एक स्वादिष्ट, संपूर्ण भोजन की तलाश में हैं। यह DASH (डायटरी अप्रोच टू स्टॉप हाइपरटेंशन) और कम वसा वाली रेसिपी है।",
"4","3 औंस सैल्मन, 1 कप पुलाव",
["3 छोटे चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (बाँटा हुआ)","2 बड़ी गाजर (छिली हुई और छोटे टुकड़ों में कटी हुई)","2 छोटी तोरी (टुकड़ों में कटी हुई)","1 मध्यम पीला प्याज़ (छोटे टुकड़ों में कटा हुआ)","1/2 छोटा चम्मच पिसी काली मिर्च","2 कप ब्राउन राइस (पका हुआ)","2 कप पानी","2 कप पालक (कटा हुआ)","4 (3 औंस के) सैल्मन फ़िले","1/4 छोटा चम्मच लहसुन पाउडर","8 औंस बेबी बेला मशरूम (स्लाइस किए हुए)","2 कली लहसुन (बारीक कटी हुई)","2 छोटे चम्मच कम सोडियम वाला सोया सॉस"],
["कड़ाही को मध्यम आँच पर पहले से गरम करें। कड़ाही गरम होने पर 1 छोटा चम्मच तेल डालें और तली पर फैलाने के लिए घुमाएँ। सब्ज़ियाँ और 1/4 छोटा चम्मच काली मिर्च डालें; बीच-बीच में चलाते हुए नरम होना शुरू होने तक पकाएँ, 3–4 मिनट।","कड़ाही में चावल और पालक डालें और बीच-बीच में चलाते हुए पकाएँ, जब तक चावल गरम न हो जाएँ और पालक गल न जाए, 2–3 मिनट। ढक दें और अलग रख दें।","एक और मध्यम कड़ाही को मध्यम-तेज़ आँच पर पहले से गरम करें।","जब तक कड़ाही गरम हो रही हो, फ़िले को पेपर टॉवल से थपथपाकर सुखाएँ और त्वचा वाला हिस्सा नीचे की ओर रखकर प्लेट पर रखें; ऊपर की ओर 1/4 छोटा चम्मच लहसुन पाउडर और 1/4 छोटा चम्मच काली मिर्च छिड़कें।","कड़ाही गरम होने पर 1 छोटा चम्मच तेल डालें और तली पर फैलाने के लिए घुमाएँ। सैल्मन को त्वचा वाला हिस्सा नीचे की ओर रखकर डालें और एक बार पलटते हुए तब तक पकाएँ जब तक त्वचा कुरकुरी और गूदा अपारदर्शी न हो जाए, हर तरफ़ 3–4 मिनट। एक साफ़ प्लेट में निकालें और ऊपर से एल्यूमीनियम फ़ॉइल से ढीला ढक दें। (अगले चरण के लिए कड़ाही रखें)।","कड़ाही को पेपर टॉवल से पोंछकर साफ़ करें और वापस मध्यम-तेज़ आँच पर रखें; बचा हुआ 1 छोटा चम्मच तेल डालें और तली पर फैलाने के लिए घुमाएँ। मशरूम और 2 कली लहसुन डालें; बीच-बीच में चलाते हुए नरम होने तक पकाएँ, 4–5 मिनट।","कड़ाही में सोया सॉस डालें और तरल सूखने तक 1–2 मिनट और पकाते रहें; आँच से उतार लें।","परोसने के लिए चावल, सैल्मन और मशरूम को प्लेटों में बाँटें।"]))
